package android.content; import android.net.Uri; import java.util.*; public class Intent {private String action,pkg;private Uri data;private final Map<String,Object> extras=new HashMap<>();public Intent(String a){action=a;}public Intent(Intent i){action=i.action;pkg=i.pkg;data=i.data;extras.putAll(i.extras);}public String getAction(){return action;}public Intent setPackage(String p){pkg=p;return this;}public String getPackage(){return pkg;}public Intent setData(Uri u){data=u;return this;}public Uri getData(){return data;}public Intent putExtra(String k,Object v){extras.put(k,v);return this;}@SuppressWarnings("unchecked") public <T>T getParcelableExtra(String k){return (T)extras.get(k);}}
